/// State vector: (x, z, vx, vz, theta, q).
type State = [f64; 6];

#[derive(Clone, Copy, PartialEq)]
enum Phase {
    Pad,
    Rail,
    Ascent,
    Descent,
}

fn derivative(
    t: f64,
    s: State,
    phase: Phase,
    rocket: &Rocket,
    motor: &Motor,
    env: &Environment,
    vehicle: &PlanarVehicle,
    wind: &WindProfile,
) -> State {
    let [_x, z, vx, vz, theta, q] = s;
