        let mut state = [0.0; STATE_LEN];
        state[VELOCITY..VELOCITY + 3].copy_from_slice(&[6.0, 8.0, 10.0]);
        state[ATTITUDE] = 1.0;

        let rate = derivative(
            motor.burn_time(),
            state,
            FlightPhase::Ascent,
            &rocket,
            &motor,
            &env,
            &vehicle,
            &Wind3DProfile::calm(),
            [0.0, 0.0, 1.0],
