        .unwrap();
        let mass = rocket.dry_mass_kg + motor.mass_at(motor.burn_time());
        let actual_normal_force = [
            rate[VELOCITY] * mass,
            rate[VELOCITY + 1] * mass,
            rate[VELOCITY + 2] * mass,
