}

pub fn builtin_schema(kind: BuiltinSchema) -> ImportSchema {
    let (schema_id, device, time, altitude) = match kind {
        BuiltinSchema::PerfectFliteCsv => ("edge.perfectflite.csv-v1", "PerfectFlite", "Time", "Altitude"),
        BuiltinSchema::Rrc3Csv => ("edge.rrc3.csv-v1", "Missile Works RRC3", "Time", "Altitude"),
        BuiltinSchema::BlueRavenCsv => ("edge.blueraven.csv-v1", "Featherweight Blue Raven", "time_s", "altitude_m"),
    };
    ImportSchema {
        schema_version: EVIDENCE_SCHEMA_VERSION,
        schema_id: schema_id.into(),
        format: ImportFormat::Csv {
            delimiter: ",".into(),
            has_header: true,
        },
        source: SourceSchema {
