                {proposal.valid ? <CheckCircle size={17} weight="fill" /> : <Warning size={17} weight="fill" />}
                <strong>{proposal.valid ? "Validated" : "Revision required"}</strong>
                <span>{proposal.commands.length} command{proposal.commands.length === 1 ? "" : "s"}</span>
              </div>
              <div className="proposal-lines">
                {proposal.commands.map((command) => (
                  <div key={command.index} className={command.error ? "has-error" : ""}>
                    <code>{command.text}</code>
                    {command.error && <span>{command.error}</span>}
                  </div>
                ))}
              </div>
              {diff && (
                <div className="proposal-impact">
                  <span><strong>{changeCount}</strong> state changes</span>
                  <span className={diff.studies_made_stale.length > 0 ? "warning" : ""}>
                    <strong>{diff.studies_made_stale.length}</strong> studies made stale
                  </span>
                  <span><strong>1</strong> atomic journal entry</span>
                </div>
              )}
            </>
          )}
        </div>

        <div className="copilot-actions">
          <button type="button" className="button-secondary" onClick={() => void preview()} disabled={busy !== null || lines.length === 0}>
            {busy === "preview" ? "Checking…" : "Preview changes"}
          </button>
          <button type="button" className="button-primary" onClick={() => void apply()} disabled={!proposal?.valid || busy !== null}>
            {busy === "apply" ? "Applying…" : "Approve & apply"}
            <ArrowRight size={14} weight="bold" />
          </button>
        </div>
      </div>
    </div>
  );
}
import { useEffect, useRef, useState } from "react";
import {
  IDLE,
  reduceDrag,
  type DragEvent,
  type DragState,
  type DragTarget,
} from "../core/dragCommit";
import type { Command } from "../core/types";

interface Props {
  label: string;
  target: DragTarget;
  min: number;
  max: number;
  step: number;
  debounceMs?: number;
  onPreview: (preview: { id: number; param: string; value: number }) => void;
  onCommit: (command: Command) => void;
}

const RELEASE_KEYS = new Set([
  "ArrowLeft",
  "ArrowRight",
  "ArrowUp",
  "ArrowDown",
  "Home",
  "End",
  "PageUp",
  "PageDown",
]);

export default function DragSlider({
  label,
  target,
  min,
  max,
  step,
  debounceMs = 120,
  onPreview,
  onCommit,
}: Props) {
  const state = useRef<DragState>(IDLE);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [value, setValue] = useState(target.startValue);

  const clearPreviewTimer = () => {
    if (timer.current) clearTimeout(timer.current);
    timer.current = null;
  };

  useEffect(() => clearPreviewTimer, []);
  useEffect(() => {
    if (!state.current.target) setValue(target.startValue);
  }, [target.startValue]);

  const advance = (event: DragEvent, immediatePreview = false) => {
    const outcome = reduceDrag(state.current, event);
    state.current = outcome.state;
    if (outcome.preview) {
      clearPreviewTimer();
      if (immediatePreview) onPreview(outcome.preview);
      else {
        timer.current = setTimeout(() => {
          onPreview(outcome.preview!);
          timer.current = null;
        }, debounceMs);
      }
    }
    if (outcome.command) onCommit(outcome.command);
    return outcome;
  };

  const begin = () => {
    if (!state.current.target) advance({ type: "start", target });
  };

  const move = (next: number) => {
    begin();
    setValue(next);
    advance({ type: "move", value: next });
  };

  const release = () => {
    clearPreviewTimer();
    advance({ type: "release" });
  };

  const cancel = () => {
    clearPreviewTimer();
    const outcome = advance({ type: "cancel" }, true);
    setValue(outcome.preview?.value ?? target.startValue);
  };

  return (
    <label className="drag-slider">
      <span>{label}</span>
      <input
        aria-label={label}
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        onPointerDown={(event) => {
          event.currentTarget.setPointerCapture?.(event.pointerId);
          begin();
        }}
        onPointerUp={release}
        onPointerCancel={cancel}
        onChange={(event) => move(Number(event.target.value))}
        onKeyDown={(event) => {
          if (event.key === "Escape") {
            event.preventDefault();
            cancel();
          } else if (RELEASE_KEYS.has(event.key)) begin();
        }}
        onKeyUp={(event) => {
          if (RELEASE_KEYS.has(event.key)) release();
        }}
      />
      <output>{(value * 1000).toFixed(1)} mm</output>
    </label>
  );
}

